module.exports = [
{ e: "🌊", art: { b: "🌊", s: ["🐳", "🐠", "🐙", "🤿"], c: ["#0F3D5E", "#2C8AB0"] },
pt: { h: "O vovô transformou uma caixa enorme num submarino, com janelas redondas desenhadas e um periscópio de rolo de papel-toalha. “Este é o Pipoca I”, anunciou. “Por 30 noites, vamos mergulhar cada vez mais fundo.” O Pipoca, o gato de verdade, entrou na caixa primeiro e se recusou a sair.", t: "O grande oceano azul", f: "O oceano cobre a maior parte do planeta e guarda quase toda a água da Terra. Foi no mar que a vida começou, há bilhões de anos. Hoje ele abriga baleias gigantes, peixes de todas as cores, corais, polvos e criaturas tão estranhas que parecem de outro mundo.", x: "Cerca de 97% de toda a água da Terra está nos oceanos! E a maior parte do fundo do mar ainda não foi explorada de perto por ninguém.", s: ["A profundidade média do oceano é de quase 4 quilômetros.", "O mar ajuda a controlar o clima do planeta, guardando e espalhando calor.", "Milhões de pessoas no mundo vivem da pesca e de trabalhos ligados ao mar."], ex: { t: "Quanto é 97%?", m: "uma garrafa de 1 litro com água, um copinho, uma colher de chá, corante azul (opcional)", p: ["Imagine que a garrafa cheia é toda a água da Terra. Pinte de azul, se quiser.", "Tire um copinho pequeno de água: essa é mais ou menos toda a água doce do mundo, incluindo o gelo.", "Agora pegue só uma gotinha da colher: é a água doce fácil de beber, em rios e lagos. Quase tudo é oceano!"] }, at: "Diário de bordo", m: "um caderninho, lápis de cor", p: ["Faça a capa do seu diário de bordo do submarino, com seu nome como capitão.", "Na primeira página, desenhe o mar visto da praia, com o horizonte.", "Escreva: “Mergulho 1: o oceano é enorme!”."], q: "O que você mais gostaria de encontrar no fundo do mar?" },
en: { h: "Grandpa turned a huge box into a submarine, with round windows drawn on and a paper-towel-roll periscope. “This is the Popcorn I,” he announced. “For 30 nights, we'll dive deeper and deeper.” Popcorn, the real cat, climbed into the box first and refused to come out.", t: "The great blue ocean", f: "The ocean covers most of the planet and holds almost all of Earth's water. Life began in the sea billions of years ago. Today it's home to giant whales, fish of every color, corals, octopuses and creatures so strange they seem to come from another world.", x: "About 97% of all the water on Earth is in the oceans! And most of the sea floor has never been explored up close by anyone.", s: ["The ocean's average depth is almost 4 kilometers (2.5 miles).", "The sea helps control the planet's climate by storing and spreading heat.", "Millions of people around the world make a living from fishing and sea-related work."], ex: { t: "How much is 97%?", m: "a 1-liter bottle of water, a small cup, a teaspoon, blue food coloring (optional)", p: ["Imagine the full bottle is all the water on Earth. Color it blue if you like.", "Pour out a small cupful: that's roughly all the fresh water in the world, including ice.", "Now take just one drop on the spoon: that's the easy-to-drink fresh water in rivers and lakes. Almost everything is ocean!"] }, at: "Ship's log", m: "a small notebook, colored pencils", p: ["Make the cover of your submarine's log with your name as captain.", "On the first page, draw the sea as seen from the beach, with the horizon.", "Write: “Dive 1: the ocean is enormous!”"], q: "What would you most like to find at the bottom of the sea?" },
es: { h: "El abuelo convirtió una caja enorme en un submarino, con ventanas redondas dibujadas y un periscopio hecho con un tubo de papel de cocina. “Este es el Palomita I”, anunció. “Durante 30 noches vamos a sumergirnos cada vez más profundo.” Palomita, el gato de verdad, se metió primero en la caja y se negó a salir.", t: "El gran océano azul", f: "El océano cubre la mayor parte del planeta y guarda casi toda el agua de la Tierra. La vida empezó en el mar hace miles de millones de años. Hoy alberga ballenas gigantes, peces de todos los colores, corales, pulpos y criaturas tan extrañas que parecen de otro mundo.", x: "¡Cerca del 97% de toda el agua de la Tierra está en los océanos! Y la mayor parte del fondo del mar todavía no fue explorada de cerca por nadie.", s: ["La profundidad media del océano es de casi 4 kilómetros.", "El mar ayuda a controlar el clima del planeta, guardando y repartiendo el calor.", "Millones de personas en el mundo viven de la pesca y de trabajos relacionados con el mar."], ex: { t: "¿Cuánto es 97%?", m: "una botella de 1 litro con agua, un vasito, una cucharita, colorante azul (opcional)", p: ["Imagina que la botella llena es toda el agua de la Tierra. Píntala de azul, si quieres.", "Saca un vasito pequeño de agua: esa es más o menos toda el agua dulce del mundo, incluido el hielo.", "Ahora toma solo una gotita con la cuchara: es el agua dulce fácil de beber, en ríos y lagos. ¡Casi todo es océano!"] }, at: "Diario de a bordo", m: "un cuadernito, lápices de colores", p: ["Haz la tapa de tu diario de a bordo del submarino, con tu nombre como capitán.", "En la primera página, dibuja el mar visto desde la playa, con el horizonte.", "Escribe: “Inmersión 1: ¡el océano es enorme!”."], q: "¿Qué te gustaría encontrar en el fondo del mar?" } },

{ e: "🔦", art: { b: "🔦", s: ["☀️", "🌙", "🦑", "🐟"], c: ["#0B1B3A", "#2C5A8A"] },
pt: { h: "Leo apagou metade das luzes da sala e depois todas, e Nina ia descrevendo: “Agora estamos na zona da luz… agora no crepúsculo… agora na meia-noite!”. O vovô gostou da brincadeira: “O oceano tem andares, como um prédio, e cada um é mais escuro que o outro.”", t: "Os andares do oceano", f: "Os cientistas dividem o oceano em zonas. Até uns 200 metros fica a zona da luz, onde vivem a maioria dos peixes e as algas. Depois vem a zona do crepúsculo, com pouca luz. Abaixo de mil metros começa a zona da meia-noite, escura como breu. E lá embaixo ficam o abismo e as fossas, os lugares mais fundos.", x: "Abaixo de uns mil metros, a luz do Sol nunca chega! Os animais de lá vivem num escuro total e muitos produzem a própria luz.", s: ["Quanto mais fundo, mais frio: no fundo do oceano, a água fica perto de 2 a 4 graus.", "As algas só vivem onde chega luz, porque precisam dela para fazer seu alimento.", "Muitos animais sobem à noite das zonas fundas para comer perto da superfície e descem de dia."], ex: { t: "Oceano em camadas", m: "um copo alto e transparente, mel ou xarope, detergente, água com corante azul, óleo de cozinha", p: ["Coloque devagar no copo, um de cada vez: primeiro o mel, depois o detergente, depois a água azul e por fim o óleo.", "Despeje bem devagar, pela parede do copo, para não misturar.", "Veja as camadas separadas, como os andares do oceano! Os líquidos mais pesados ficam embaixo."] }, at: "Prédio do oceano", m: "papel comprido, lápis de cor", p: ["Pinte faixas do azul-claro no alto até o preto embaixo.", "Desenhe em cada faixa um animal: peixes coloridos em cima, lulas no meio e peixes estranhos no fundo.", "Escreva no diário: “Mergulho 2: descobri os andares do mar”."], q: "Em que andar do oceano você gostaria de morar se fosse um peixe?" },
en: { h: "Leo turned off half the living room lights and then all of them, while Nina narrated: “Now we're in the sunlight zone… now the twilight… now midnight!” Grandpa loved the game: “The ocean has floors, like a building, and each one is darker than the last.”", t: "The ocean's floors", f: "Scientists divide the ocean into zones. Down to about 200 meters (650 feet) is the sunlight zone, where most fish and algae live. Then comes the twilight zone, with little light. Below about a thousand meters begins the midnight zone, pitch black. And at the very bottom are the abyss and the trenches, the deepest places.", x: "Below about a thousand meters, sunlight never reaches! Animals there live in total darkness, and many make their own light.", s: ["The deeper you go, the colder it gets: at the bottom of the ocean, the water is about 2 to 4 degrees Celsius.", "Algae live only where light reaches, because they need it to make their food.", "Many animals rise from the deep zones at night to eat near the surface and sink back down by day."], ex: { t: "Ocean in layers", m: "a tall clear glass, honey or syrup, dish soap, water with blue coloring, cooking oil", p: ["Slowly add to the glass, one at a time: first honey, then dish soap, then blue water and finally oil.", "Pour very slowly down the side of the glass so they don't mix.", "See the separate layers, like the ocean's floors! The heaviest liquids stay at the bottom."] }, at: "Ocean building", m: "long paper, colored pencils", p: ["Color bands from light blue at the top to black at the bottom.", "Draw an animal in each band: colorful fish up top, squid in the middle and strange fish at the bottom.", "Write in your log: “Dive 2: I discovered the ocean's floors.”"], q: "Which floor of the ocean would you live on if you were a fish?" },
es: { h: "Leo apagó la mitad de las luces de la sala y después todas, y Nina iba narrando: “Ahora estamos en la zona de la luz… ahora en el crepúsculo… ¡ahora en la medianoche!”. Al abuelo le encantó el juego: “El océano tiene pisos, como un edificio, y cada uno es más oscuro que el anterior.”", t: "Los pisos del océano", f: "Los científicos dividen el océano en zonas. Hasta unos 200 metros está la zona de la luz, donde viven la mayoría de los peces y las algas. Después viene la zona del crepúsculo, con poca luz. Por debajo de los mil metros empieza la zona de medianoche, oscura como boca de lobo. Y allá abajo están el abismo y las fosas, los lugares más profundos.", x: "¡Por debajo de unos mil metros, la luz del Sol nunca llega! Los animales de allí viven en una oscuridad total, y muchos producen su propia luz.", s: ["Cuanto más profundo, más frío: en el fondo del océano, el agua está entre 2 y 4 grados.", "Las algas solo viven donde llega la luz, porque la necesitan para fabricar su alimento.", "Muchos animales suben de noche desde las zonas profundas para comer cerca de la superficie y bajan de día."], ex: { t: "Océano en capas", m: "un vaso alto y transparente, miel o almíbar, detergente, agua con colorante azul, aceite de cocina", p: ["Pon despacio en el vaso, de a uno: primero la miel, después el detergente, después el agua azul y por último el aceite.", "Échalos muy despacio, por la pared del vaso, para que no se mezclen.", "¡Mira las capas separadas, como los pisos del océano! Los líquidos más pesados quedan abajo."] }, at: "Edificio del océano", m: "papel largo, lápices de colores", p: ["Pinta franjas desde el celeste arriba hasta el negro abajo.", "Dibuja un animal en cada franja: peces de colores arriba, calamares en el medio y peces raros en el fondo.", "Escribe en el diario: “Inmersión 2: descubrí los pisos del mar”."], q: "¿En qué piso del océano te gustaría vivir si fueras un pez?" } },

{ e: "🏄", art: { b: "🏄", s: ["🌊", "🌙", "🏖️", "💨"], c: ["#0B3A5A", "#4AA0D4"] },
pt: { h: "Na praia, Leo construiu um castelo de areia bem perto da água. Uma hora depois, o mar tinha subido e levado tudo! “O mar está com raiva de mim?”, perguntou, emburrado. O vovô riu: “Não, é a maré! E quem puxa a maré é a Lua.”", t: "Ondas e marés", f: "As ondas são criadas principalmente pelo vento que sopra sobre a água. Quanto mais forte e mais longe o vento sopra, maiores as ondas. Já as marés são a subida e a descida do nível do mar, que acontecem duas vezes por dia, por causa da força da Lua e do Sol puxando a água.", x: "Em Nazaré, em Portugal, surfistas já desceram ondas de mais de 25 metros, da altura de um prédio de 8 andares!", s: ["No Maranhão, a diferença entre a maré alta e a baixa pode passar de 6 metros, uma das maiores do Brasil.", "Uma onda não leva a água para longe: a água sobe e desce, e a energia é que viaja.", "Os tsunamis são ondas gigantes causadas por terremotos no fundo do mar, e não pelo vento."], ex: { t: "Onda na garrafa", m: "uma garrafa transparente com tampa, água, corante azul, óleo de cozinha", p: ["Encha um terço da garrafa com água e corante azul.", "Complete com óleo, deixando um pouco de ar, e feche bem a tampa.", "Deite a garrafa e balance devagar de um lado para o outro: ondas aparecem lá dentro! Vá mais rápido e veja as ondas crescerem."] }, at: "Tabela da maré", m: "papel, lápis de cor", p: ["Desenhe a mesma praia duas vezes: com a maré alta e com a maré baixa.", "Na maré baixa, desenhe as poças com siris, conchas e estrelas-do-mar que aparecem.", "Escreva no diário: “Mergulho 3: a Lua puxa o mar”."], q: "Você prefere brincar na praia com a maré alta ou com a maré baixa?" },
en: { h: "At the beach, Leo built a sandcastle very close to the water. An hour later, the sea had risen and washed it all away! “Is the sea mad at me?” he asked, sulking. Grandpa laughed: “No, it's the tide! And what pulls the tide is the Moon.”", t: "Waves and tides", f: "Waves are made mostly by wind blowing over the water. The stronger and farther the wind blows, the bigger the waves. Tides are the rising and falling of sea level, which happens twice a day because the Moon and Sun pull on the water.", x: "In Nazaré, Portugal, surfers have ridden waves more than 25 meters (80 feet) tall, as high as an 8-story building!", s: ["In some places, like Canada's Bay of Fundy, the difference between high and low tide can be more than 15 meters (50 feet).", "A wave doesn't carry water far away: the water moves up and down, and it's the energy that travels.", "Tsunamis are giant waves caused by earthquakes under the sea, not by wind."], ex: { t: "Wave in a bottle", m: "a clear bottle with a cap, water, blue food coloring, cooking oil", p: ["Fill a third of the bottle with water and blue coloring.", "Top it up with oil, leaving a little air, and screw the cap on tight.", "Lay the bottle on its side and rock it gently: waves appear inside! Go faster and watch them grow."] }, at: "Tide chart", m: "paper, colored pencils", p: ["Draw the same beach twice: at high tide and at low tide.", "At low tide, draw the tide pools with crabs, shells and starfish that appear.", "Write in your log: “Dive 3: the Moon pulls the sea.”"], q: "Do you prefer playing at the beach at high tide or low tide?" },
es: { h: "En la playa, Leo construyó un castillo de arena muy cerca del agua. ¡Una hora después, el mar había subido y se lo había llevado todo! “¿El mar está enojado conmigo?”, preguntó, enfurruñado. El abuelo se rió: “¡No, es la marea! Y quien tira de la marea es la Luna.”", t: "Olas y mareas", f: "Las olas se forman sobre todo por el viento que sopla sobre el agua. Cuanto más fuerte y más lejos sopla el viento, más grandes son las olas. Las mareas son la subida y la bajada del nivel del mar, que ocurren dos veces por día, porque la Luna y el Sol atraen el agua.", x: "¡En Nazaré, Portugal, hay surfistas que bajaron olas de más de 25 metros, la altura de un edificio de 8 pisos!", s: ["En algunos lugares, como la Patagonia argentina, la diferencia entre la marea alta y la baja puede superar los 10 metros.", "Una ola no lleva el agua lejos: el agua sube y baja, y lo que viaja es la energía.", "Los tsunamis son olas gigantes causadas por terremotos en el fondo del mar, y no por el viento."], ex: { t: "Ola en la botella", m: "una botella transparente con tapa, agua, colorante azul, aceite de cocina", p: ["Llena un tercio de la botella con agua y colorante azul.", "Complétala con aceite, dejando un poco de aire, y ciérrala bien.", "Acuesta la botella y muévela despacio de un lado al otro: ¡aparecen olas adentro! Hazlo más rápido y mira cómo crecen."] }, at: "Tabla de mareas", m: "papel, lápices de colores", p: ["Dibuja la misma playa dos veces: con marea alta y con marea baja.", "En la marea baja, dibuja los charcos con cangrejos, conchas y estrellas de mar que aparecen.", "Escribe en el diario: “Inmersión 3: la Luna tira del mar”."], q: "¿Prefieres jugar en la playa con la marea alta o con la marea baja?" } },

{ e: "🦐", art: { b: "🦐", s: ["🔬", "🌿", "🐋", "✨"], c: ["#0B4E4E", "#3AA0A0"] },
pt: { h: "Nina pegou um pouco de água do mar num copo e olhou contra a luz. “Não tem nada aqui”, disse. O vovô deu uma lupa para ela: “Olha de novo, bem de pertinho.” Ela viu pontinhos se mexendo! “São seres minúsculos que fazem o mar funcionar”, explicou ele.", t: "O plâncton, os pequenos gigantes", f: "Plâncton é o nome dado a seres, muitos deles minúsculos, que flutuam e vão para onde a água leva. Há o fitoplâncton, algas microscópicas que fazem fotossíntese como as plantas, e o zooplâncton, animaizinhos como larvas e o krill. Eles são a base da comida de quase tudo no mar.", x: "O fitoplâncton produz cerca de metade do oxigênio do planeta! Então, de cada duas respiradas que você dá, mais ou menos uma veio do mar.", s: ["A palavra plâncton vem do grego e quer dizer “errante”, aquele que vaga por aí.", "A baleia-azul, o maior animal do mundo, se alimenta de krill, uns bichinhos parecidos com camarões pequenos.", "Algumas algas do plâncton brilham no escuro quando a água se agita."], ex: { t: "Desafio do plâncton que flutua", m: "um pote alto e transparente com água, massinha, papel, palitos, penas ou pedacinhos de esponja, um relógio", p: ["Faça uma bolinha de massinha do tamanho de uma ervilha: ela é o seu “plâncton”. Solte na água e conte quanto tempo leva para afundar.", "Agora invente um plâncton com o mesmo pedaço de massinha, mas com “braços” de papel, palitos ou penas.", "Qual demora mais para afundar? O plâncton de verdade tem espinhos e formatos que ajudam a flutuar perto da luz."] }, at: "Cadeia alimentar do mar", m: "papel, lápis de cor", p: ["Desenhe uma escada: no primeiro degrau, o fitoplâncton; depois o krill; depois um peixe; e no topo, uma baleia ou um tubarão.", "Ligue tudo com setas.", "Escreva no diário: “Mergulho 4: os menores sustentam os maiores”."], q: "Por que você acha que seres tão pequenos são tão importantes?" },
en: { h: "Nina scooped some seawater into a glass and held it up to the light. “There's nothing here,” she said. Grandpa handed her a magnifying glass: “Look again, really close.” She saw little dots moving! “Those are tiny beings that keep the sea running,” he explained.", t: "Plankton, the little giants", f: "Plankton is the name for living things, many of them tiny, that drift wherever the water carries them. There's phytoplankton, microscopic algae that make food from sunlight like plants, and zooplankton, little animals like larvae and krill. They are the base of the food chain for almost everything in the sea.", x: "Phytoplankton produces about half the oxygen on the planet! So for about every two breaths you take, one came from the sea.", s: ["The word plankton comes from Greek and means “wanderer,” one who drifts around.", "The blue whale, the biggest animal in the world, feeds on krill, little creatures that look like small shrimp.", "Some plankton algae glow in the dark when the water is stirred."], ex: { t: "Floating plankton challenge", m: "a tall clear jar of water, play dough, paper, toothpicks, feathers or bits of sponge, a clock", p: ["Make a pea-sized ball of play dough: it's your “plankton.” Drop it in the water and time how long it takes to sink.", "Now invent a plankton using the same bit of dough but with paper, toothpick or feather “arms.”", "Which one takes longer to sink? Real plankton has spines and shapes that help it float near the light."] }, at: "Ocean food chain", m: "paper, colored pencils", p: ["Draw a staircase: on the first step, phytoplankton; then krill; then a fish; and at the top, a whale or a shark.", "Connect them all with arrows.", "Write in your log: “Dive 4: the smallest feed the biggest.”"], q: "Why do you think such tiny beings are so important?" },
es: { h: "Nina tomó un poco de agua de mar en un vaso y la miró a contraluz. “No hay nada”, dijo. El abuelo le dio una lupa: “Mira otra vez, bien de cerquita.” ¡Vio puntitos que se movían! “Son seres diminutos que hacen funcionar el mar”, explicó él.", t: "El plancton, los pequeños gigantes", f: "Plancton es el nombre de seres, muchos de ellos diminutos, que flotan y van adonde los lleva el agua. Está el fitoplancton, algas microscópicas que fabrican su alimento con la luz como las plantas, y el zooplancton, animalitos como larvas y el krill. Son la base de la comida de casi todo en el mar.", x: "¡El fitoplancton produce cerca de la mitad del oxígeno del planeta! Así que, de cada dos respiraciones que haces, más o menos una vino del mar.", s: ["La palabra plancton viene del griego y quiere decir “errante”, el que anda vagando.", "La ballena azul, el animal más grande del mundo, se alimenta de krill, unos bichitos parecidos a camarones pequeños.", "Algunas algas del plancton brillan en la oscuridad cuando el agua se agita."], ex: { t: "Desafío del plancton que flota", m: "un frasco alto y transparente con agua, plastilina, papel, palillos, plumas o pedacitos de esponja, un reloj", p: ["Haz una bolita de plastilina del tamaño de una arveja: es tu “plancton”. Suéltala en el agua y cuenta cuánto tarda en hundirse.", "Ahora inventa un plancton con el mismo pedazo de plastilina, pero con “brazos” de papel, palillos o plumas.", "¿Cuál tarda más en hundirse? El plancton de verdad tiene espinas y formas que lo ayudan a flotar cerca de la luz."] }, at: "Cadena alimentaria del mar", m: "papel, lápices de colores", p: ["Dibuja una escalera: en el primer escalón, el fitoplancton; después el krill; después un pez; y arriba de todo, una ballena o un tiburón.", "Une todo con flechas.", "Escribe en el diario: “Inmersión 4: los más chicos alimentan a los más grandes”."], q: "¿Por qué crees que seres tan pequeños son tan importantes?" } },

{ e: "🐠", art: { b: "🐠", s: ["🐟", "🫧", "🐡", "🪸"], c: ["#0B3A5A", "#E0A02C"] },
pt: { h: "No aquário da clínica do dentista, Leo ficou hipnotizado com um peixinho laranja que abria e fechava a boca sem parar. “Ele está falando com a gente?”, perguntou. Nina riu. O vovô explicou: “Ele está respirando! Os peixes tiram o oxigênio da água pelas guelras.”", t: "Os peixes", f: "Os peixes vivem na água, respiram por guelras e a maioria tem o corpo coberto de escamas e nadadeiras para nadar. A água entra pela boca, passa pelas guelras, que pegam o oxigênio, e sai pelos lados da cabeça. Muitos peixes têm uma bolsa de ar, a bexiga natatória, para subir e descer na água.", x: "Existem mais de 35 mil espécies de peixes, mais ou menos metade de todas as espécies de animais com coluna vertebral do mundo!", s: ["Os peixes têm uma linha nos lados do corpo que sente o movimento da água, como um sexto sentido.", "O peixe-palhaço vive escondido entre os tentáculos das anêmonas, que não o queimam.", "Alguns peixes, como o baiacu, se enchem de água para parecer maiores e assustar os predadores."], ex: { t: "Peixe de papel que nada", m: "papel cartão ou de embrulho de leite, tesoura, uma bandeja com água, detergente, um palito", p: ["Recorte um peixinho de uns 5 centímetros, com um corte fininho do meio até o rabo, e um furinho redondo no fim do corte.", "Coloque o peixe boiando na água, bem parada.", "Pingue uma gota de detergente no furinho do rabo com o palito: o peixe dispara para a frente! O sabão quebra a “pele” da água atrás dele."] }, at: "Aquário de papel", m: "um prato de papel ou caixa, papel colorido, lápis de cor, linha", p: ["Pinte o fundo de azul e desenhe areia, pedras e algas.", "Recorte peixes de vários formatos e cores e pendure com linha.", "Escreva no diário: “Mergulho 5: peixes respiram água!”."], q: "Se você fosse um peixe, de que cor seria e onde moraria?" },
en: { h: "At the dentist's office aquarium, Leo was hypnotized by a little orange fish that kept opening and closing its mouth. “Is it talking to us?” he asked. Nina laughed. Grandpa explained: “It's breathing! Fish take oxygen out of the water with their gills.”", t: "Fish", f: "Fish live in water, breathe with gills, and most have bodies covered in scales and fins for swimming. Water goes in through the mouth, passes over the gills, which take out oxygen, and flows out the sides of the head. Many fish have an air sac, the swim bladder, to rise and sink in the water.", x: "There are more than 35,000 species of fish, roughly half of all the species of animals with backbones in the world!", s: ["Fish have a line along their sides that senses water movement, like a sixth sense.", "Clownfish live hidden among anemone tentacles, which don't sting them.", "Some fish, like pufferfish, puff up with water to look bigger and scare predators."], ex: { t: "Swimming paper fish", m: "card stock or a milk carton, scissors, a tray of water, dish soap, a toothpick", p: ["Cut out a fish about 5 cm (2 inches) long, with a thin slit from the middle to the tail and a little round hole at the end of the slit.", "Float the fish on very still water.", "Put a drop of dish soap in the tail hole with the toothpick: the fish zooms forward! The soap breaks the water's “skin” behind it."] }, at: "Paper aquarium", m: "a paper plate or box, colored paper, colored pencils, thread", p: ["Color the background blue and draw sand, rocks and seaweed.", "Cut out fish of different shapes and colors and hang them with thread.", "Write in your log: “Dive 5: fish breathe water!”"], q: "If you were a fish, what color would you be and where would you live?" },
es: { h: "En la pecera del consultorio del dentista, Leo quedó hipnotizado con un pececito naranja que abría y cerraba la boca sin parar. “¿Nos está hablando?”, preguntó. Nina se rió. El abuelo explicó: “¡Está respirando! Los peces sacan el oxígeno del agua con las branquias.”", t: "Los peces", f: "Los peces viven en el agua, respiran por branquias y la mayoría tiene el cuerpo cubierto de escamas y aletas para nadar. El agua entra por la boca, pasa por las branquias, que toman el oxígeno, y sale por los costados de la cabeza. Muchos peces tienen una bolsa de aire, la vejiga natatoria, para subir y bajar en el agua.", x: "¡Existen más de 35.000 especies de peces, más o menos la mitad de todas las especies de animales con columna vertebral del mundo!", s: ["Los peces tienen una línea a los costados del cuerpo que siente el movimiento del agua, como un sexto sentido.", "El pez payaso vive escondido entre los tentáculos de las anémonas, que no lo pican.", "Algunos peces, como el pez globo, se inflan de agua para parecer más grandes y asustar a los depredadores."], ex: { t: "Pez de papel que nada", m: "cartulina o cartón de leche, tijera, una bandeja con agua, detergente, un palillo", p: ["Recorta un pececito de unos 5 centímetros, con un corte finito desde el medio hasta la cola y un agujerito redondo al final del corte.", "Pon el pez a flotar en agua bien quieta.", "Pon una gota de detergente en el agujerito de la cola con el palillo: ¡el pez sale disparado hacia adelante! El jabón rompe la “piel” del agua detrás de él."] }, at: "Acuario de papel", m: "un plato de papel o una caja, papel de colores, lápices de colores, hilo", p: ["Pinta el fondo de azul y dibuja arena, piedras y algas.", "Recorta peces de varias formas y colores y cuélgalos con hilo.", "Escribe en el diario: “Inmersión 5: ¡los peces respiran agua!”."], q: "Si fueras un pez, ¿de qué color serías y dónde vivirías?" } },

{ e: "🦈", art: { b: "🦈", s: ["🦷", "🌊", "🐟", "🌳"], c: ["#1B2A3A", "#4A6A8A"] },
pt: { h: "Leo ouviu uma música de filme de tubarão e começou a “nadar” pela sala, fazendo cara de malvado. O vovô riu e contou: “Os tubarões têm fama de vilões, mas quase nunca atacam pessoas. E sabe o mais incrível? Eles existem há mais tempo que as árvores!”", t: "Os tubarões", f: "Os tubarões são peixes com esqueleto feito de cartilagem, o mesmo material flexível da ponta do nosso nariz e das orelhas. Existem mais de 500 espécies, de tubarões menores que uma mão até o gigante tubarão-baleia. Eles têm um olfato poderoso e sentidos especiais para encontrar presas.", x: "Os tubarões existem há mais de 400 milhões de anos, antes mesmo das primeiras árvores e dos dinossauros! E um tubarão pode perder e trocar milhares de dentes durante a vida.", s: ["O tubarão-baleia é o maior peixe do mundo, pode passar de 12 metros e come só plâncton e peixinhos.", "Os tubarões não têm bexiga natatória: um fígado cheio de óleo ajuda a não afundar.", "Muitas espécies de tubarão estão ameaçadas por causa da pesca exagerada."], ex: { t: "Fígado de óleo", m: "dois potinhos pequenos com tampa (como os de remédio ou filme), água, óleo de cozinha, uma bacia com água", p: ["Encha um potinho com água e o outro com óleo, e feche bem os dois.", "Coloque os dois na bacia de água.", "O potinho de óleo boia mais! O óleo é mais leve que a água, e é por isso que o fígado oleoso ajuda o tubarão a flutuar."] }, at: "Ficha de defesa do tubarão", m: "papel, lápis de cor", p: ["Desenhe um tubarão sorridente com o título “Tubarão não é vilão”.", "Escreva três fatos que você aprendeu que mostram como eles são importantes para o mar.", "Escreva no diário: “Mergulho 6: tubarões são mais velhos que as árvores!”."], q: "Por que você acha que os tubarões ganharam fama de malvados?" },
en: { h: "Leo heard music from a shark movie and started “swimming” around the living room, making a mean face. Grandpa laughed and said, “Sharks have a reputation as villains, but they almost never attack people. And you know the most amazing part? They've been around longer than trees!”", t: "Sharks", f: "Sharks are fish with skeletons made of cartilage, the same bendy material as the tip of your nose and your ears. There are more than 500 species, from sharks smaller than your hand to the giant whale shark. They have a powerful sense of smell and special senses for finding prey.", x: "Sharks have existed for more than 400 million years, even before the first trees and the dinosaurs! And a shark can lose and replace thousands of teeth in its lifetime.", s: ["The whale shark is the biggest fish in the world, can grow longer than 12 meters (40 feet) and eats only plankton and small fish.", "Sharks don't have a swim bladder: an oil-filled liver helps keep them from sinking.", "Many shark species are threatened by overfishing."], ex: { t: "Oily liver", m: "two small containers with lids (like pill bottles), water, cooking oil, a basin of water", p: ["Fill one container with water and the other with oil, and close them both tightly.", "Put both in the basin of water.", "The oil container floats higher! Oil is lighter than water, which is why an oily liver helps sharks stay afloat."] }, at: "Shark defense card", m: "paper, colored pencils", p: ["Draw a smiling shark with the title “Sharks aren't villains.”", "Write three facts you learned that show how important they are to the sea.", "Write in your log: “Dive 6: sharks are older than trees!”"], q: "Why do you think sharks got a reputation for being mean?" },
es: { h: "Leo escuchó la música de una película de tiburones y empezó a “nadar” por la sala poniendo cara de malo. El abuelo se rió y contó: “Los tiburones tienen fama de villanos, pero casi nunca atacan a las personas. ¿Y sabes lo más increíble? ¡Existen desde antes que los árboles!”", t: "Los tiburones", f: "Los tiburones son peces con esqueleto de cartílago, el mismo material flexible de la punta de la nariz y las orejas. Hay más de 500 especies, desde tiburones más chicos que una mano hasta el gigante tiburón ballena. Tienen un olfato poderoso y sentidos especiales para encontrar presas.", x: "¡Los tiburones existen desde hace más de 400 millones de años, antes incluso que los primeros árboles y los dinosaurios! Y un tiburón puede perder y cambiar miles de dientes durante su vida.", s: ["El tiburón ballena es el pez más grande del mundo, puede superar los 12 metros y come solo plancton y pececitos.", "Los tiburones no tienen vejiga natatoria: un hígado lleno de aceite los ayuda a no hundirse.", "Muchas especies de tiburones están amenazadas por la pesca excesiva."], ex: { t: "Hígado de aceite", m: "dos recipientes pequeños con tapa (como los de remedios), agua, aceite de cocina, una palangana con agua", p: ["Llena un recipiente con agua y el otro con aceite, y ciérralos bien.", "Pon los dos en la palangana con agua.", "¡El de aceite flota más! El aceite es más liviano que el agua, y por eso el hígado aceitoso ayuda al tiburón a flotar."] }, at: "Ficha en defensa del tiburón", m: "papel, lápices de colores", p: ["Dibuja un tiburón sonriente con el título “El tiburón no es villano”.", "Escribe tres datos que aprendiste que muestran lo importantes que son para el mar.", "Escribe en el diario: “Inmersión 6: ¡los tiburones son más viejos que los árboles!”."], q: "¿Por qué crees que los tiburones tienen fama de malos?" } },

{ e: "🐋", art: { b: "🐋", s: ["🎶", "💙", "🌊", "🐳"], c: ["#0B2A5A", "#3A6AC2"] },
pt: { h: "O vovô colocou para tocar uma gravação estranha: gemidos longos, assobios e roncos que pareciam música. “Isso é o canto da baleia-jubarte”, contou. “E todo inverno, milhares delas vêm ter filhotes no litoral do Brasil.” Nina fechou os olhos para ouvir melhor.", t: "As baleias", f: "As baleias não são peixes: são mamíferos, como nós. Respiram ar por um buraco no alto da cabeça, amamentam os filhotes e têm sangue quente. Algumas têm dentes, como a cachalote, e outras têm barbatanas, uma espécie de pente na boca para filtrar comida.", x: "A baleia-azul é o maior animal que já existiu na Terra, maior que qualquer dinossauro! Ela pode passar de 30 metros, e o coração dela é do tamanho de um carro pequeno.", s: ["As jubartes cantam músicas longas que podem ser ouvidas a quilômetros de distância debaixo da água.", "Entre julho e novembro, muitas jubartes visitam o arquipélago de Abrolhos, na Bahia, para ter filhotes.", "Depois que a caça às baleias foi proibida, a população de jubartes do Brasil cresceu muito."], ex: { t: "O som que viaja pela mesa", m: "uma mesa de madeira, um lápis, um parceiro", p: ["Peça para alguém bater de leve com o lápis numa ponta da mesa. Escute com a cabeça levantada.", "Agora encoste a orelha na outra ponta da mesa e peça para a pessoa bater do mesmo jeito.", "Fica muito mais alto! O som viaja melhor pela madeira, e também pela água, do que pelo ar. Por isso as baleias se ouvem de tão longe."] }, at: "A baleia em tamanho real", m: "barbante comprido, fita métrica, um espaço grande (quintal, garagem ou corredor)", p: ["Meça 30 metros de barbante, ou o máximo que conseguir, e estique no chão.", "Deite no começo do barbante e veja quantas crianças caberiam deitadas ao longo dele.", "Escreva no diário: “Mergulho 7: a baleia-azul é o maior animal de todos os tempos”."], q: "O que você acha que as baleias dizem umas para as outras quando cantam?" },
en: { h: "Grandpa played a strange recording: long moans, whistles and grunts that sounded like music. “That's a humpback whale singing,” he said. “And every winter, thousands of them come to have their babies off the coast of Brazil.” Nina closed her eyes to listen better.", t: "Whales", f: "Whales aren't fish: they're mammals, like us. They breathe air through a hole on top of their heads, nurse their babies and are warm-blooded. Some have teeth, like sperm whales, and others have baleen, a kind of comb in the mouth for filtering food.", x: "The blue whale is the biggest animal that has ever lived on Earth, bigger than any dinosaur! It can grow longer than 30 meters (100 feet), and its heart is the size of a small car.", s: ["Humpbacks sing long songs that can be heard for kilometers underwater.", "Between July and November, many humpbacks visit the Abrolhos islands, in Brazil, to give birth.", "After whale hunting was banned, Brazil's humpback population grew a lot."], ex: { t: "Sound that travels through a table", m: "a wooden table, a pencil, a partner", p: ["Ask someone to tap lightly with a pencil at one end of the table. Listen with your head up.", "Now press your ear to the other end of the table and have them tap the same way.", "It's much louder! Sound travels better through wood, and through water too, than through air. That's why whales can hear each other from so far away."] }, at: "A life-size whale", m: "long string, a tape measure, a big space (yard, garage or hallway)", p: ["Measure 30 meters (100 feet) of string, or as much as you can, and stretch it on the ground.", "Lie down at the start of the string and see how many kids could lie end to end along it.", "Write in your log: “Dive 7: the blue whale is the biggest animal of all time.”"], q: "What do you think whales say to each other when they sing?" },
es: { h: "El abuelo puso una grabación extraña: gemidos largos, silbidos y ronquidos que parecían música. “Es el canto de la ballena jorobada”, contó. “Y cada invierno, miles de ellas llegan a tener sus crías frente a la costa de Brasil.” Nina cerró los ojos para escuchar mejor.", t: "Las ballenas", f: "Las ballenas no son peces: son mamíferos, como nosotros. Respiran aire por un agujero arriba de la cabeza, amamantan a sus crías y tienen sangre caliente. Algunas tienen dientes, como el cachalote, y otras tienen barbas, una especie de peine en la boca para filtrar la comida.", x: "¡La ballena azul es el animal más grande que existió en la Tierra, más grande que cualquier dinosaurio! Puede superar los 30 metros, y su corazón es del tamaño de un auto pequeño.", s: ["Las jorobadas cantan canciones largas que se pueden oír a kilómetros de distancia bajo el agua.", "Entre julio y noviembre, muchas jorobadas visitan el archipiélago de Abrolhos, en Brasil, para tener crías.", "Después de que se prohibió la caza de ballenas, la población de jorobadas creció mucho."], ex: { t: "El sonido que viaja por la mesa", m: "una mesa de madera, un lápiz, un compañero", p: ["Pide a alguien que golpee suavemente con el lápiz en una punta de la mesa. Escucha con la cabeza levantada.", "Ahora apoya la oreja en la otra punta de la mesa y pide que golpee igual.", "¡Se oye mucho más fuerte! El sonido viaja mejor por la madera, y también por el agua, que por el aire. Por eso las ballenas se oyen desde tan lejos."] }, at: "La ballena en tamaño real", m: "cordel largo, cinta métrica, un espacio grande (patio, garaje o pasillo)", p: ["Mide 30 metros de cordel, o lo más que puedas, y estíralo en el suelo.", "Acuéstate al comienzo del cordel y mira cuántos niños cabrían acostados a lo largo.", "Escribe en el diario: “Inmersión 7: la ballena azul es el animal más grande de todos los tiempos”."], q: "¿Qué crees que se dicen las ballenas cuando cantan?" } },

{ e: "🐬", art: { b: "🐬", s: ["🎵", "🌊", "💤", "🩷"], c: ["#0B3A6B", "#5AA0E0"] },
pt: { h: "Num passeio de barco, um grupo de golfinhos apareceu nadando ao lado, saltando e assobiando. Nina gritou de alegria. “Eles estão conversando!”, disse Leo. “Estão mesmo”, confirmou o vovô. “E cada golfinho tem um assobio só dele, como se fosse o seu nome.”", t: "Os golfinhos", f: "Os golfinhos são mamíferos marinhos muito inteligentes e brincalhões. Vivem em grupos, caçam juntos e se comunicam com assobios e cliques. Eles usam os cliques como um sonar: o som bate nas coisas e volta, mostrando onde estão os peixes, mesmo no escuro.", x: "Os golfinhos dormem com metade do cérebro de cada vez! Assim, uma metade descansa enquanto a outra fica acordada para respirar e vigiar.", s: ["Cada golfinho cria um assobio próprio, e os outros usam esse som para chamá-lo, como um nome.", "Na Amazônia vive o boto-cor-de-rosa, um golfinho de rio que fica mais rosado quando adulto.", "Os golfinhos precisam subir à superfície para respirar, pelo buraco no alto da cabeça."], ex: { t: "Assobio-nome", m: "a família reunida, um pano para vendar os olhos", p: ["Cada pessoa inventa um assobio curtinho que vai ser o seu “nome de golfinho”. Todos ensaiam juntos.", "Uma pessoa fica de olhos vendados no meio da sala. As outras se espalham.", "Alguém faz o assobio de outra pessoa: quem está vendado precisa apontar para quem foi “chamado”. Vocês reconhecem os nomes só pelo som?"] }, at: "Ficha do boto", m: "papel, lápis de cor rosa e azul", p: ["Desenhe um golfinho do mar saltando e, ao lado, um boto-cor-de-rosa num rio da Amazônia.", "Escreva as diferenças entre os dois.", "Escreva no diário: “Mergulho 8: golfinhos têm nomes!”."], q: "Que assobio você escolheria como seu nome de golfinho?" },
en: { h: "On a boat trip, a group of dolphins appeared swimming alongside, leaping and whistling. Nina squealed with joy. “They're talking!” said Leo. “They really are,” Grandpa confirmed. “And each dolphin has its own special whistle, like a name.”", t: "Dolphins", f: "Dolphins are very intelligent, playful marine mammals. They live in groups, hunt together and communicate with whistles and clicks. They use clicks like sonar: the sound bounces off things and comes back, showing where the fish are, even in the dark.", x: "Dolphins sleep with half their brain at a time! That way one half rests while the other stays awake to breathe and keep watch.", s: ["Each dolphin creates its own whistle, and others use that sound to call it, like a name.", "In the Amazon lives the pink river dolphin, which gets pinker as it grows up.", "Dolphins have to come up to the surface to breathe through the hole on top of their heads."], ex: { t: "Whistle names", m: "the family together, a cloth for a blindfold", p: ["Everyone invents a short whistle that will be their “dolphin name.” Practice together.", "One person stands blindfolded in the middle of the room. The others spread out.", "Someone makes another person's whistle: the blindfolded person has to point to whoever was “called.” Can you recognize names just by sound?"] }, at: "River dolphin card", m: "paper, pink and blue colored pencils", p: ["Draw an ocean dolphin leaping and, next to it, a pink river dolphin in an Amazon river.", "Write the differences between the two.", "Write in your log: “Dive 8: dolphins have names!”"], q: "What whistle would you choose as your dolphin name?" },
es: { h: "En un paseo en barco, un grupo de delfines apareció nadando al costado, saltando y silbando. Nina gritó de alegría. “¡Están conversando!”, dijo Leo. “Así es”, confirmó el abuelo. “Y cada delfín tiene un silbido propio, como si fuera su nombre.”", t: "Los delfines", f: "Los delfines son mamíferos marinos muy inteligentes y juguetones. Viven en grupos, cazan juntos y se comunican con silbidos y chasquidos. Usan los chasquidos como un sonar: el sonido rebota en las cosas y vuelve, mostrando dónde están los peces, incluso en la oscuridad.", x: "¡Los delfines duermen con la mitad del cerebro por vez! Así, una mitad descansa mientras la otra se queda despierta para respirar y vigilar.", s: ["Cada delfín crea un silbido propio, y los demás usan ese sonido para llamarlo, como un nombre.", "En la Amazonía vive el delfín rosado, un delfín de río que se vuelve más rosado de adulto.", "Los delfines tienen que subir a la superficie para respirar por el agujero de arriba de la cabeza."], ex: { t: "Silbido-nombre", m: "la familia reunida, un pañuelo para vendar los ojos", p: ["Cada persona inventa un silbido cortito que será su “nombre de delfín”. Todos ensayan juntos.", "Una persona se queda con los ojos vendados en el medio de la sala. Las otras se reparten.", "Alguien hace el silbido de otra persona: quien tiene los ojos vendados tiene que señalar a quién “llamaron”. ¿Reconocen los nombres solo por el sonido?"] }, at: "Ficha del delfín rosado", m: "papel, lápices rosa y azul", p: ["Dibuja un delfín de mar saltando y, al lado, un delfín rosado en un río de la Amazonía.", "Escribe las diferencias entre los dos.", "Escribe en el diario: “Inmersión 8: ¡los delfines tienen nombre!”."], q: "¿Qué silbido elegirías como tu nombre de delfín?" } },

{ e: "🐙", art: { b: "🐙", s: ["💙", "🖤", "🦑", "🫧"], c: ["#3A0B4E", "#9A3AB0"] },
pt: { h: "No mercado de peixe, Nina viu um polvo e contou os braços: “Oito!”. O vovô fez uma pergunta difícil: “E quantos corações vocês acham que ele tem?”. Leo chutou um. Nina chutou dois. “Três!”, revelou o vovô. “E o sangue dele é azul!”", t: "Polvos e lulas", f: "Os polvos são animais sem ossos, parentes dos caracóis. Têm oito braços cheios de ventosas, que sentem gosto e cheiro do que tocam. São muito inteligentes: abrem potes, resolvem labirintos e mudam de cor e de textura em menos de um segundo para se esconder.", x: "O polvo tem três corações e sangue azul! E a maior parte dos neurônios dele fica nos braços, como se cada braço pensasse um pouquinho sozinho.", s: ["Para fugir, polvos e lulas soltam uma nuvem de tinta escura e disparam como um jato, empurrando água.", "Um polvo consegue passar por qualquer buraco em que caiba o seu bico, a única parte dura do corpo.", "A lula-gigante pode ter mais de 10 metros e tem os maiores olhos do reino animal, do tamanho de um prato."], ex: { t: "Jato de lula", m: "uma bexiga, uma banheira ou bacia grande com água", p: ["Encha a bexiga de ar e segure a boca dela fechada.", "Coloque a bexiga na água, com a boca virada para trás, e solte.", "Ela dispara para a frente! As lulas e os polvos enchem o corpo de água e a expulsam com força, como um jato."] }, at: "Polvo camaleão", m: "papel branco, lápis de cor, tesoura", p: ["Desenhe e recorte um polvo de papel.", "Coloque-o em cima de objetos diferentes da casa e pinte outro polvo com as cores e manchas de cada lugar, para ele se “camuflar”.", "Escreva no diário: “Mergulho 9: três corações e sangue azul!”."], q: "Se você pudesse mudar de cor como um polvo, para que usaria esse poder?" },
en: { h: "At the fish market, Nina saw an octopus and counted its arms: “Eight!” Grandpa asked a tough question: “And how many hearts do you think it has?” Leo guessed one. Nina guessed two. “Three!” Grandpa revealed. “And its blood is blue!”", t: "Octopuses and squid", f: "Octopuses are boneless animals related to snails. They have eight arms covered in suckers that taste and smell what they touch. They're very intelligent: they open jars, solve mazes and change color and texture in less than a second to hide.", x: "An octopus has three hearts and blue blood! And most of its neurons are in its arms, as if each arm did a little thinking on its own.", s: ["To escape, octopuses and squid squirt a cloud of dark ink and jet away by pushing out water.", "An octopus can squeeze through any hole its beak fits through, the only hard part of its body.", "The giant squid can be more than 10 meters (33 feet) long and has the biggest eyes in the animal kingdom, as big as dinner plates."], ex: { t: "Squid jet", m: "a balloon, a bathtub or large basin of water", p: ["Blow up the balloon and pinch the neck closed.", "Put the balloon in the water with the neck facing backward, and let go.", "It zooms forward! Squid and octopuses fill their bodies with water and push it out hard, like a jet."] }, at: "Chameleon octopus", m: "white paper, colored pencils, scissors", p: ["Draw and cut out a paper octopus.", "Place it on different objects around the house and color new octopuses with the colors and patterns of each spot so they “camouflage.”", "Write in your log: “Dive 9: three hearts and blue blood!”"], q: "If you could change color like an octopus, what would you use that power for?" },
es: { h: "En el mercado de pescado, Nina vio un pulpo y contó sus brazos: “¡Ocho!”. El abuelo hizo una pregunta difícil: “¿Y cuántos corazones creen que tiene?”. Leo dijo uno. Nina dijo dos. “¡Tres!”, reveló el abuelo. “¡Y su sangre es azul!”", t: "Pulpos y calamares", f: "Los pulpos son animales sin huesos, parientes de los caracoles. Tienen ocho brazos llenos de ventosas, que sienten el gusto y el olor de lo que tocan. Son muy inteligentes: abren frascos, resuelven laberintos y cambian de color y de textura en menos de un segundo para esconderse.", x: "¡El pulpo tiene tres corazones y sangre azul! Y la mayor parte de sus neuronas está en los brazos, como si cada brazo pensara un poquito solo.", s: ["Para escapar, los pulpos y calamares sueltan una nube de tinta oscura y salen disparados como un chorro, empujando agua.", "Un pulpo puede pasar por cualquier agujero en el que quepa su pico, la única parte dura de su cuerpo.", "El calamar gigante puede medir más de 10 metros y tiene los ojos más grandes del reino animal, del tamaño de un plato."], ex: { t: "Chorro de calamar", m: "un globo, una bañera o palangana grande con agua", p: ["Infla el globo y sostén la boca cerrada.", "Pon el globo en el agua, con la boca mirando hacia atrás, y suéltalo.", "¡Sale disparado hacia adelante! Los calamares y los pulpos llenan su cuerpo de agua y la expulsan con fuerza, como un chorro."] }, at: "Pulpo camaleón", m: "papel blanco, lápices de colores, tijera", p: ["Dibuja y recorta un pulpo de papel.", "Ponlo encima de distintos objetos de la casa y pinta otro pulpo con los colores y manchas de cada lugar, para que se “camufle”.", "Escribe en el diario: “Inmersión 9: ¡tres corazones y sangre azul!”."], q: "Si pudieras cambiar de color como un pulpo, ¿para qué usarías ese poder?" } },

{ e: "🪸", art: { b: "🪸", s: ["🐠", "🐢", "🌈", "🐡"], c: ["#5A1B3A", "#E06A8A"] },
pt: { h: "O vovô mostrou fotos de um recife de coral cheio de cores, com peixes por todos os lados. “Parece um jardim embaixo da água”, disse Nina. “Parece, mas não é”, respondeu o vovô. “Os corais são animais! E a cidade de Recife ganhou esse nome por causa dos recifes que ficam na frente dela.”", t: "Os recifes de coral", f: "Os corais são animais minúsculos, chamados pólipos, que vivem em colônias e constroem um esqueleto duro de calcário. Dentro deles vivem algas que fazem fotossíntese e dão cor e alimento aos corais. Juntos, ao longo de milhares de anos, eles formam recifes enormes.", x: "Os recifes de coral ocupam menos de 1% do fundo do mar, mas abrigam cerca de um quarto de todas as espécies marinhas! A Grande Barreira de Corais, na Austrália, é tão grande que pode ser vista do espaço.", s: ["Quando a água do mar esquenta demais, as algas vão embora e os corais ficam brancos. Isso se chama branqueamento.", "O Brasil tem corais que só existem aqui, como o coral-cérebro de Abrolhos.", "Os recifes protegem as praias, porque quebram a força das ondas antes que cheguem à areia."], ex: { t: "Concha no vinagre", m: "duas conchinhas ou pedaços de giz escolar, dois copos, água, vinagre", p: ["Coloque uma conchinha num copo com água e a outra num copo com vinagre.", "Observe por algumas horas: no vinagre aparecem bolhinhas, e a concha vai se desmanchando.", "Quando o mar fica mais ácido por causa da poluição, os corais e as conchas sofrem algo parecido. Por isso é tão importante cuidar do planeta!"] }, at: "Recife de massinha", m: "massinha colorida, conchas, uma tampa de caixa", p: ["Monte um recife na tampa com massinhas em formatos de cérebro, galhos e leques.", "Coloque peixes, uma tartaruga e um polvo de massinha escondidos entre os corais.", "Escreva no diário: “Mergulho 10: corais são animais!”."], q: "Que animal você gostaria de encontrar num recife de coral?" },
en: { h: "Grandpa showed photos of a colorful coral reef with fish everywhere. “It looks like an underwater garden,” said Nina. “It looks like one, but it isn't,” Grandpa answered. “Corals are animals! And the Brazilian city of Recife was named for the reefs in front of it.”", t: "Coral reefs", f: "Corals are tiny animals called polyps that live in colonies and build a hard limestone skeleton. Inside them live algae that use sunlight to make food and give corals their color and nourishment. Together, over thousands of years, they build huge reefs.", x: "Coral reefs cover less than 1% of the sea floor but shelter about a quarter of all marine species! Australia's Great Barrier Reef is so big it can be seen from space.", s: ["When seawater gets too warm, the algae leave and the corals turn white. That's called bleaching.", "Brazil has corals found nowhere else, like the brain coral of Abrolhos.", "Reefs protect beaches by breaking the force of the waves before they reach the sand."], ex: { t: "Shell in vinegar", m: "two small shells or pieces of school chalk, two glasses, water, vinegar", p: ["Put one shell in a glass of water and the other in a glass of vinegar.", "Watch for a few hours: bubbles appear in the vinegar, and the shell slowly dissolves.", "When the sea becomes more acidic because of pollution, corals and shells suffer something similar. That's why caring for the planet matters so much!"] }, at: "Play dough reef", m: "colored play dough, shells, a box lid", p: ["Build a reef on the lid with play dough shaped like brains, branches and fans.", "Hide play dough fish, a turtle and an octopus among the corals.", "Write in your log: “Dive 10: corals are animals!”"], q: "Which animal would you like to meet on a coral reef?" },
es: { h: "El abuelo mostró fotos de un arrecife de coral lleno de colores, con peces por todas partes. “Parece un jardín bajo el agua”, dijo Nina. “Parece, pero no lo es”, respondió el abuelo. “¡Los corales son animales! Y la ciudad brasileña de Recife recibió ese nombre por los arrecifes que tiene enfrente.”", t: "Los arrecifes de coral", f: "Los corales son animales diminutos, llamados pólipos, que viven en colonias y construyen un esqueleto duro de piedra caliza. Dentro de ellos viven algas que fabrican alimento con la luz y les dan color y comida a los corales. Juntos, a lo largo de miles de años, forman arrecifes enormes.", x: "¡Los arrecifes de coral ocupan menos del 1% del fondo del mar, pero albergan cerca de una cuarta parte de todas las especies marinas! La Gran Barrera de Coral, en Australia, es tan grande que se puede ver desde el espacio.", s: ["Cuando el agua del mar se calienta demasiado, las algas se van y los corales se vuelven blancos. Eso se llama blanqueamiento.", "Brasil tiene corales que solo existen allí, como el coral cerebro de Abrolhos.", "Los arrecifes protegen las playas, porque rompen la fuerza de las olas antes de que lleguen a la arena."], ex: { t: "Concha en vinagre", m: "dos conchitas o pedazos de tiza escolar, dos vasos, agua, vinagre", p: ["Pon una conchita en un vaso con agua y la otra en un vaso con vinagre.", "Observa durante unas horas: en el vinagre aparecen burbujitas y la concha se va deshaciendo.", "Cuando el mar se vuelve más ácido por la contaminación, los corales y las conchas sufren algo parecido. ¡Por eso es tan importante cuidar el planeta!"] }, at: "Arrecife de plastilina", m: "plastilina de colores, conchas, una tapa de caja", p: ["Arma un arrecife en la tapa con plastilinas en forma de cerebro, ramas y abanicos.", "Esconde peces, una tortuga y un pulpo de plastilina entre los corales.", "Escribe en el diario: “Inmersión 10: ¡los corales son animales!”."], q: "¿Qué animal te gustaría encontrar en un arrecife de coral?" } },
];
